describe('Checkout Flow - Full Order Confirmation', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should successfully complete checkout with valid credentials and item in cart', () => {
    // Login with standard user
    cy.get('[name="user-name"]').type('standard_user');
    cy.get('[name="password"]').type('secret_sauce');
    cy.get('[name="login-button"]').click();

    // Add backpack to cart
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').click();

    // Navigate to cart
    cy.get('[data-testid="shopping-cart-link"]').click();

    // Proceed to checkout
    cy.get('[data-testid="checkout"]').click();

    // Fill in checkout form
    cy.get('[name="firstName"]').type('Saif');
    cy.get('[name="lastName"]').type('Afzal');
    cy.get('[name="postalCode"]').type('20001');
    cy.get('[name="continue"]').click();

    // Verify overview page
    cy.get('[data-testid="continue-button"]').should('be.visible');
    cy.get('[data-testid="item-total"]').should('contain', '$109.97');

    // Complete order
    cy.get('[data-testid="finish-button"]').click();

    // Verify confirmation page
    cy.get('[data-testid="complete-header"]').should('be.visible');
    cy.get('[data-testid="complete-header"]').should('contain', 'Thank you for your order!');
    cy.get('[data-testid="confirmation-message"]').should('contain', 'Your order has been placed');
  });

  it('should handle checkout with invalid postal code and prevent order completion', () => {
    // Login with standard user
    cy.get('[name="user-name"]').type('standard_user');
    cy.get('[name="password"]').type('secret_sauce');
    cy.get('[name="login-button"]').click();

    // Add backpack to cart
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').click();

    // Navigate to cart
    cy.get('[data-testid="shopping-cart-link"]').click();

    // Proceed to checkout
    cy.get('[data-testid="checkout"]').click();

    // Fill in checkout form with invalid postal code
    cy.get('[name="firstName"]').type('Saif');
    cy.get('[name="lastName"]').type('Afzal');
    cy.get('[name="postalCode"]').type('invalid-zip');
    cy.get('[name="continue"]').click();

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Please enter a valid postal code');

    // Verify finish button is disabled or not visible
    cy.get('[data-testid="finish-button"]').should('not.exist');
  });
});
